findings.codeql_raw_query:
/**
 * @name CLI Command Injection
 * @description Detects flow from sys.argv to subprocess calls
 * @kind path-problem
 * @problem.severity error
 * @id py/cli-command-injection
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module CliInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source = API::moduleImport("sys").getMember("argv").asSource()
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("subprocess").getMember(["Popen", "call", "check_call", "run", "check_output"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module CliInjectionFlow = TaintTracking::Global<CliInjectionConfig>;
import CliInjectionFlow::PathGraph

from CliInjectionFlow::PathNode source, CliInjectionFlow::PathNode sink
where CliInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential command injection from $@", source.getNode(), "command line arguments"
